import * as XLSX from 'xlsx';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';

export const exportarAExcel = (datos, mes, año) => {
    const workbook = XLSX.utils.book_new();

    // Hoja de resumen
    const resumenData = [
        ['RESUMEN DE GASTOS', `${mes}/${año}`],
        [''],
        ['Concepto', 'Monto', 'Propiedad', 'Fecha'],
        ...datos.gastos.map(gasto => [
            gasto.concepto,
            gasto.monto,
            gasto.propiedad || 'General',
            format(new Date(gasto.fecha), 'dd/MM/yyyy')
        ]),
        [''],
        ['TOTAL GENERAL', datos.totalGeneral],
        ['TOTAL POR PROPIEDAD', ''],
        ...Object.entries(datos.totalesPorPropiedad).map(([propiedad, total]) => [
            propiedad,
            total
        ])
    ];

    const resumenSheet = XLSX.utils.aoa_to_sheet(resumenData);
    XLSX.utils.book_append_sheet(workbook, resumenSheet, 'Resumen');

    // Hojas individuales por inquilino
    Object.entries(datos.detalleInquilinos).forEach(([inquilino, detalle]) => {
        const inquilinoData = [
            [`DETALLE PARA: ${inquilino}`],
            [`Período: ${mes}/${año}`],
            [''],
            ['Servicio', 'Monto Total', 'Tu Parte'],
            ...detalle.servicios.map(servicio => [
                servicio.concepto,
                servicio.montoTotal,
                servicio.montoIndividual
            ]),
            [''],
            ['TOTAL A PAGAR', '', detalle.totalAPagar]
        ];

        const inquilinoSheet = XLSX.utils.aoa_to_sheet(inquilinoData);
        XLSX.utils.book_append_sheet(workbook, inquilinoSheet, inquilino.substring(0, 30));
    });

    // Guardar archivo
    const nombreArchivo = `Gastos_${mes}_${año}.xlsx`;
    XLSX.writeFile(workbook, nombreArchivo);
};

export const exportarPDF = (contenidoRef) => {
    // Función para exportar a PDF (requiere react-to-print)
    window.print();
};
